        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = Source, Text = "Orang yang moralnya kuat karena apa? Karena pengalaman. Ia belajar dari pengalaman.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Saya pegang ajaran Multatuli bahwa kewajiban manusia adalah menjadi manusia.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Karya sastra para pengarang avant garde hanya mengganggu tidur pribadi-pribadi dalam lingkaran elite kekuasaan, yang khawatir suatu kali cengkeramanya atas rakyat bawahan bisa terlepas.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Berbahagialah dia yang makan dari keringatnya sendiri, bersuka karena usahanya sendiri dan maju karena pengalamannya sendiri.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Tak ada cinta muncul mendadak, karena dia anak kebudayaan, bukan batu dari langit.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Hidup bisa memberikan segala pada barang siapa tahu dan pandai menerima.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Cerita tentang kesenangan selalu tidak menarik. Itu bukan cerita tentang manusia dan kehidupannya, tapi tentang surga, dan jelas tidak terjadi di atas bumi kita ini.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Duniaku bukan jabatan, pangkat, gaji, dan kecurangan. Duniaku bumi manusia dengan persoalannya.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Semakin tinggi sekolah bukan berarti semakin menghabiskan makanan orang lain. Harus semakin mengenal batas.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Kau terpelajar, cobalah bersetia pada kata hati.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Melawan pada yang berilmu dan berpengetahuan adalah menyerahkan diri pada maut dan kehinaan.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Kalian boleh maju dalam pelajaran, mungkin mencapai deretan gelar kesarjanaan apa saja, tapi tanpa mencintai sastra, kalian tinggal hanya hewan yang pandai.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Barang siapa tidak tahu bersetia pada azas, dia terbuka terhadap segala kejahatan: dijahati atau menjahati.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Nama berganti seribu kali dalam sehari, makna tetap.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Kalau hati dan pikiran manusia sudah tak mampu mencapai lagi, bukankah hanya pada Tuhan juga orang berseru?", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Benih yang tidak sempurna akan punah sebelum berbuah.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Dengan ilmu pengetahuan modern, binatang buas akan menjadi lebih buas, dan manusia keji akan semakin keji. Tapi jangan dilupakan, dengan ilmu pengetahuan modern binatang-binatang yang sebuas-buasnya juga bisa ditundukkan.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Tanpa mempelajari bahasa sendiri pun orang takkan mengenal bangsanya sendiri.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Kehidupan ini seimbang, Tuan. Barangsiapa hanya memandang pada keceriaannya saja, dia orang gila. Barangsiapa memandang pada penderitaannya saja, dia sakit.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Kehidupan lebih nyata daripada pendapat siapa pun tentang kenyataan.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Selama penderitaan datang dari manusia, dia bukan bencana alam, dia pun pasti bisa dilawan oleh manusia.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Revolusi Perancis mendudukkan harga manusia pada tempatnya yang tepat. Dengan hanya memandang manusia pada satu sisi, sisi penderitaan semata, orang akan kehilangan sisinya yang lain. Dari sisi penderitaan saja, yang datang pada kita hanya dendam, dendam semata.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Semua yang terjadi di kolong langit ini adalah urusan setiap orang yang berpikir.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Kalau kemanusiaan tersinggung, semua orang yang berperasaan dan berpikiran waras ikut tersinggung, kecuali orang gila dan orang yang memang berjiwa kriminal, biar pun dia sarjana.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Persahabatan lebih kuat daripada panasnya permusuhan.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Dahulu, nenek moyangmu selalu mengajarkan, tidak ada yang lebih sederhana daripada hidup: lahir, makan-minum, tumbuh, beranak-pinak dan berbuat kebajikan.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Setiap hak yang berlebihan adalah penindasan.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Masa terbaik dalam hidup seseorang adalah masa ia dapat menggunakan kebebasan yang telah direbutnya sendiri.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Tak mungkin orang dapat mencintai negeri dan bangsanya kalau orang tak mengenal kertas-kertas tentangnya, kalau dia tak mengenal sejarahnya, apalagi kalau tak pernah berbuat sesuatu kebajikan untuknya.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Setiap permulaan memang sulit. Dengan memulai setengah pekerjaan sudah selesai, kata pepatah.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Jangan Tuan terlalu percaya pada pendidikan sekolah. Seorang guru yang baik masih bisa melahirkan bandit-bandit yang sejahat-jahatnya, yang sama sekali tidak mengenal prinsip. Apalagi kalau guru itu sudah bandit pula pada dasarnya.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Tetapi manusia pun bisa mengusahakan lahirnya syarat-syarat baru, kenyataan baru, dan tidak hanya berenang di antara kenyataan-kenyataan yang telah tersedia.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Di balik setiap kehormatan mengintip kebinasaan. Di balik hidup adalah maut. Di balik persatuan adalah perpecahan. Di balik sembah adalah umpat. Maka jalan keselamatan adalah jalan tengah. Jangan terima kehormatan atau kebinasaan sepenuhnya. Jalan tengah—jalan ke arah kelestarian.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Betapa sederhana hidup ini sesungguhnya; yang pelik cuma liku dan tafsirannya.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Hidup sungguh sangat sederhana. Yang hebat-hebat hanya tafsirannya.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Setiap tulisan merupakan dunia tersendiri, yang terapung-apung antara dunia kenyataan dan dunia impian.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Orang boleh pandai setinggi langit, tapi selama ia tak menulis, ia akan hilang di dalam masyarakat dan dari sejarah.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Orang bilang ada kekuatan-kekuatan dahsyat yang tak terduga yang bisa timbul pada samudera, pada gunung berapi dan pada pribadi yang tahu benar akan tujuan hidupnya.", Author = "Pramoedya Ananta Toer" },
            new Quote { Id = Source, Text = "Pada akhirnya persoalan hidup adalah persoalan menunda mati, biarpun orang-orang yang bijaksana lebih suka mati sekali daripada berkali-kali.", Author = "Pramoedya Ananta Toer" },
